<section class="dashboard-intro"><div class="page-heading compact"><p class="eyebrow">TRANSACTION RECORDS</p><h1>Sales History</h1><p class="lead">Every recorded sale, with the product, customer, staff member, and total captured at checkout.</p></div><a class="button" href="<?= site_url('sales/create') ?>">Record a sale &rarr;</a></section>
<section class="directory"><div class="table-top"><h2>All transactions</h2><span class="pill"><?= count($sales) ?> sales</span></div><div class="table-scroll" tabindex="0" role="region" aria-label="Sales history"><table><thead><tr><th>Sale</th><th>Product</th><th>Customer</th><th>Staff</th><th>Quantity</th><th>Total (PHP)</th><th>Date</th></tr></thead><tbody><?php foreach ($sales as $sale): ?><tr><td><a class="text-link" href="<?= site_url('sales/'.$sale['id']) ?>">#<?= $sale['id'] ?></a></td><td><?= esc($sale['product_name']) ?></td><td><?= esc($sale['customer_name'] ?? 'Walk-in') ?></td><td><?= esc($sale['staff_name']) ?></td><td><?= $sale['quantity'] ?></td><td class="number"><?= peso($sale['total_price']) ?></td><td><?= esc($sale['created_at']) ?></td></tr><?php endforeach ?><?php if (! $sales): ?><tr><td colspan="7" class="empty-state">No sales have been recorded yet.</td></tr><?php endif ?></tbody></table></div><p class="table-note">Historical names and prices are preserved when directory details change.</p></section>
